const cantidad = Number(prompt("Cantidad de lecturas"));
let hallazgo = "Sin coincidencia";
for (let i = 0; i < cantidad; i = i + 1) {
  const lectura = Number(prompt("Lectura"));
  if (lectura < 0) continue;
  if (lectura >= 30) {
    hallazgo = lectura;
    break;
  }
}
console.log("Hallazgo:", hallazgo);

